package org.jlinalg.cli;

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.*;
import org.jlinalg.genetics.PlinkBedDataset;

/** Typed sparse-GRM recipe, immutable BED snapshots and complete native structure audit. */
final class SaigeGrmInputs {
    private SaigeGrmInputs() { }
    record Limits(int samples,int variants,long bytes,long genotypeCells,long matrixEntries,int threads,double memoryGiB) { }
    record Spec(Path recipe,String recipeSha256,Path prefix,String assembly,int randomMarkers,
                double cutoff,double minMaf,double maxMissing,Limits limits,Map<?,?> source) { }
    record Prepared(Spec spec,Path prefix,List<String> sampleIds,long variants,long exactEligibleMarkers,
                    long unresolvedAlleleMarkers,Map<Path,String> immutable) {
        Prepared {sampleIds=List.copyOf(sampleIds);immutable=Map.copyOf(immutable);}
        void verify()throws IOException {for(var entry:immutable.entrySet())if(!FollowupSupport.hash(entry.getKey()).equals(entry.getValue()))throw new IOException("SAIGE input changed: "+entry.getKey());if(!FollowupSupport.hash(spec.recipe).equals(spec.recipeSha256))throw new IOException("SAIGE recipe changed during execution");}
    }
    static Spec read(Path file)throws Exception {
        file=file.toAbsolutePath().normalize();if(!Files.isRegularFile(file)||Files.size(file)>2*1048576)throw new IOException("Require a UTF8 SAIGE recipe at most2MiB");byte[] raw=Files.readAllBytes(file);Map<?,?> root=map(SimpleJson.parse(StandardCharsets.UTF_8.newDecoder().decode(ByteBuffer.wrap(raw)).toString()));keys(root,Set.of("version","operation","genotypes","genotype_coding","assembly","parameters","resources"));whole(root,"version",1,1);
        if(!text(root,"operation").equals("sparse-grm"))throw new IOException("This typed recipe requires operation=sparse-grm;fit/single/gene/LD integration is separate work");
        if(!text(root,"genotype_coding").equals("diploid-autosomal-plink-bed"))throw new IOException("Declare genotype_coding=diploid-autosomal-plink-bed;no ploidy/sex-chromosome conversion is inferred");
        String assembly=text(root,"assembly");if(assembly.length()>1024||assembly.chars().anyMatch(Character::isISOControl))throw new IOException("Require an explicit single-line assembly/reference declaration");String value=text(root,"genotypes");if(value.chars().anyMatch(Character::isISOControl))throw new IOException("Genotype path contains a control character");Path prefix=Path.of(value);if(!prefix.isAbsolute())prefix=file.getParent().resolve(prefix);prefix=prefix.toAbsolutePath().normalize();
        Map<?,?> p=map(root.get("parameters"));keys(p,Set.of("random_markers","relatedness_cutoff","min_maf","max_missing","diagonal","seed"));int markers=(int)whole(p,"random_markers",1,5_000_000);double cutoff=number(p,"relatedness_cutoff",0,2),maf=number(p,"min_maf",0,.5),missing=number(p,"max_missing",0,1);whole(p,"seed",1,1);if(!text(p,"diagonal").equals("observed"))throw new IOException("The validated sparse-GRM recipe preserves observed diagonals;unit-diagonal behavior is not inferred");
        Map<?,?> r=map(root.get("resources"));keys(r,Set.of("threads","memory_chunk_gib","max_samples","max_variants","max_input_bytes","max_genotype_cells","max_matrix_entries"));int threads=(int)whole(r,"threads",1,64);double memory=number(r,"memory_chunk_gib",.001,256);int samples=(int)optional(r,"max_samples",1_000_000,1,1_000_000),variants=(int)optional(r,"max_variants",1_000_000,1,5_000_000);long bytes=optional(r,"max_input_bytes",4L*1073741824,1,64L*1024*1073741824),cells=optional(r,"max_genotype_cells",1_000_000_000,1,10_000_000_000_000L),entries=optional(r,"max_matrix_entries",20_000_000,1,1_000_000_000);
        return new Spec(file,java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(raw)),prefix,assembly,markers,cutoff,maf,missing,new Limits(samples,variants,bytes,cells,entries,threads,memory),root);
    }
    static Prepared prepare(Spec spec,Path work)throws Exception {
        var sources=new ArrayList<Path>();long bytes=0;for(String suffix:List.of(".bed",".bim",".fam")){Path source=Path.of(spec.prefix+suffix);if(!Files.isRegularFile(source))throw new IOException("Missing PLINK source: "+source);bytes=Math.addExact(bytes,Files.size(source));sources.add(source);}if(bytes>spec.limits.bytes)throw new IOException("Complete BED/BIM/FAM input exceeds max_input_bytes");if(Files.getFileStore(work).getUsableSpace()<bytes+64L*1048576)throw new IOException("Insufficient free scratch storage for immutable genotype snapshots");
        Path input=work.resolve("inputs");Files.createDirectory(input);Path prefix=input.resolve("genotypes");var immutable=new LinkedHashMap<Path,String>();int index=0;for(String suffix:List.of(".bed",".bim",".fam")){Path source=sources.get(index++),target=Path.of(prefix+suffix);String digest=FollowupSupport.hash(source);Files.copy(source,target);if(!FollowupSupport.hash(target).equals(digest))throw new IOException("Genotype source changed during snapshot");immutable.put(source,digest);immutable.put(target,digest);}
        var ids=new LinkedHashSet<String>();try(var reader=Files.newBufferedReader(Path.of(prefix+".bim"),StandardCharsets.UTF_8)){String line;while((line=line(reader,16384))!=null){if(line.isBlank())continue;String[] fields=line.strip().split("[ \\t]+");if(fields.length!=6||ids.size()>=spec.limits.variants||!ids.add(fields[1]))throw new IOException("BIM requires unique IDs,six fields and bounded variant count");int chromosome;try{chromosome=Integer.parseInt(fields[0]);}catch(NumberFormatException failure){throw new IOException("Sparse-GRM profile requires explicit autosomes1..22",failure);}if(chromosome<1||chromosome>22)throw new IOException("This diploid-autosomal recipe rejects sex/nonautosomal markers;no ploidy is inferred");}}
        if(ids.isEmpty())throw new IOException("No genotype variants supplied");var limits=new PlinkBedDataset.Limits(spec.limits.samples,spec.limits.variants,spec.limits.variants,spec.limits.bytes,1073741824L,16384);List<String> samples;long eligible=0,unresolved=0;
        try(var bed=PlinkBedDataset.open(prefix,ids,limits,PlinkBedDataset.AllelePolicy.QC_ALLOW_MISSING)){
            samples=bed.samples().stream().map(PlinkBedDataset.Sample::individualId).toList();SaigeGenotypes.cohortIndices(bed.samples(),samples);long cells=Math.multiplyExact((long)samples.size(),ids.size());if(cells>spec.limits.genotypeCells)throw new IOException("Native raw-genotype admission exceeds max_genotype_cells;declare resources explicitly or use a permitted smaller source array");
            for(var variant:bed.selectedVariants()){if(!variant.resolvedAlleles())unresolved++;double[] g=bed.readAllele1Dosages(variant);long observed=0,ac=0;for(double value:g)if(!Double.isNaN(value)){observed++;ac+=(int)value;}if(observed==0)throw new IOException("All-missing source marker has no finite GRM imputation frequency: "+variant.id()+";supply an explicitly filtered array source");double frequency=ac/(2.0*observed),maf=Math.min(frequency,1-frequency),missing=1-observed/(double)g.length;if(maf>0&&maf>=spec.minMaf&&missing<=spec.maxMissing)eligible++;}
        }
        if(ids.size()<spec.randomMarkers)throw new IOException("Fewer source markers than random_markers;review the array source");var result=new Prepared(spec,prefix,samples,ids.size(),eligible,unresolved,immutable);result.verify();return result;
    }
    static List<String> command(Prepared prepared,Path work) {
        Spec s=prepared.spec;return List.of("--plinkFile="+prepared.prefix,"--outputPrefix="+work.resolve("original-grm"),"--numRandomMarkerforSparseKin="+s.randomMarkers,"--relatednessCutoff="+s.cutoff,"--minMAFforGRM="+s.minMaf,"--maxMissingRateforGRM="+s.maxMissing,"--nThreads="+s.limits.threads,"--memoryChunk="+s.limits.memoryGiB,"--isDiagofKinSetAsOne=FALSE");
    }
    static Map<String,Object> audit(Prepared prepared,Path work)throws Exception {
        List<Path> candidates;try(var stream=Files.list(work)){candidates=stream.filter(p->p.getFileName().toString().startsWith("original-grm_relatednessCutoff_")&&p.getFileName().toString().endsWith("_randomMarkersUsed.sparseGRM.mtx")).toList();}if(candidates.size()!=1)throw new IOException("Original SAIGE omitted or duplicated its sparse-GRM output");Path original=candidates.get(0),ids=Path.of(original+".sampleIDs.txt");var sampleIds=new ArrayList<String>();try(var reader=Files.newBufferedReader(ids,StandardCharsets.UTF_8)){for(String value;(value=line(reader,16384))!=null;){if(value.isBlank())throw new IOException("Sparse-GRM sample IDs contain a blank record");sampleIds.add(value);if(sampleIds.size()>prepared.sampleIds.size())throw new IOException("Sparse-GRM sample universe grew");}}if(!sampleIds.equals(prepared.sampleIds))throw new IOException("Sparse-GRM changed source IID universe/order");
        Map<String,Object> matrix=auditMatrix(original,sampleIds.size(),prepared.spec.cutoff,prepared.spec.limits.matrixEntries);Files.copy(original,work.resolve("grm.mtx"));Files.copy(ids,work.resolve("sample-ids.txt"));if(!FollowupSupport.hash(original).equals(FollowupSupport.hash(work.resolve("grm.mtx")))||!FollowupSupport.hash(ids).equals(FollowupSupport.hash(work.resolve("sample-ids.txt"))))throw new IOException("Canonical GRM bytes differ from original outputs");var result=new LinkedHashMap<String,Object>();result.put("status","completed-with-review-warnings");result.put("operation","sparse-grm");result.put("assembly_declaration",prepared.spec.assembly);result.put("genotype_coding","explicit diploid-autosomal PLINK hard calls;no biological REF/ploidy inference");result.put("source_samples",sampleIds.size());result.put("source_variants",prepared.variants);result.put("native_exact_observed_QC_eligible_markers",prepared.exactEligibleMarkers);result.put("source_unresolved_allele_label_markers",prepared.unresolvedAlleleMarkers);result.put("original_fixed_R_seed",1);result.put("matrix",matrix);result.put("grm_sha256",FollowupSupport.hash(work.resolve("grm.mtx")));result.put("sample_ids_sha256",FollowupSupport.hash(work.resolve("sample-ids.txt")));result.put("pair_coverage","candidate-screened;not-certified-complete-above-cutoff");result.put("reference_scope","Original algorithm and floating arithmetic retained. Native audit checks complete sparse structure,sample identities,finite values,diagonal/threshold invariants and exact canonical output bytes;it does not recompute every GRM coefficient in production.");return result;
    }
    static Map<String,Object> auditMatrix(Path file,int samples,double cutoff,long maximumEntries)throws Exception {
        if(samples<1||!Double.isFinite(cutoff)||cutoff<0||maximumEntries<1)throw new IOException("Invalid GRM audit contract");long declared,count=0,offDiagonal=0,diagonalEntries=0,zeroDiagonals=0;double minimumDiagonal=Double.POSITIVE_INFINITY,maximumDiagonal=0,minimumOffDiagonal=Double.POSITIVE_INFINITY,maximumOffDiagonal=Double.NEGATIVE_INFINITY;boolean[] diagonal=new boolean[samples];long previousRow=-1,previousColumn=-1;boolean rowSorted=true,columnSorted=true;int triangle=0;
        try(var reader=Files.newBufferedReader(file,StandardCharsets.UTF_8)){
            if(!"%%MatrixMarket matrix coordinate real symmetric".equals(line(reader,16384)))throw new IOException("Require original real symmetric coordinate MatrixMarket header");String value;do{value=line(reader,16384);}while(value!=null&&(value.isBlank()||value.startsWith("%")));if(value==null)throw new IOException("Missing matrix dimensions");String[] dimensions=value.strip().split("\\s+");if(dimensions.length!=3||Long.parseLong(dimensions[0])!=samples||Long.parseLong(dimensions[1])!=samples)throw new IOException("GRM dimensions differ from source sample universe");declared=Long.parseLong(dimensions[2]);if(declared<0||declared>maximumEntries)throw new IOException("GRM stored-entry count outside declared bounds");
            while((value=line(reader,16384))!=null){if(value.isBlank()||value.startsWith("%"))continue;String[] f=value.strip().split("\\s+");if(f.length!=3||++count>declared)throw new IOException("Invalid/excess GRM entry");int i=Integer.parseInt(f[0])-1,j=Integer.parseInt(f[1])-1;double x=Double.parseDouble(f[2]);if(i<0||i>=samples||j<0||j>=samples||!Double.isFinite(x))throw new IOException("Out-of-range/nonfinite GRM entry");long row=((long)i<<32)|Integer.toUnsignedLong(j),column=((long)j<<32)|Integer.toUnsignedLong(i);rowSorted&=row>previousRow;columnSorted&=column>previousColumn;if(!rowSorted&&!columnSorted)throw new IOException("GRM coordinates duplicate or lack original row/column ordering");previousRow=row;previousColumn=column;
                if(i==j){if(diagonal[i]||x<0)throw new IOException("Duplicate/negative observed GRM diagonal");diagonal[i]=true;diagonalEntries++;if(x==0)zeroDiagonals++;minimumDiagonal=Math.min(minimumDiagonal,x);maximumDiagonal=Math.max(maximumDiagonal,x);}else{int orientation=i>j?1:-1;if(triangle!=0&&triangle!=orientation)throw new IOException("Symmetric GRM contains both triangles");triangle=orientation;if(x<(double)(float)cutoff)throw new IOException("Sparse-GRM off-diagonal coefficient below the original float cutoff");offDiagonal++;minimumOffDiagonal=Math.min(minimumOffDiagonal,x);maximumOffDiagonal=Math.max(maximumOffDiagonal,x);}
            }
        }
        if(count!=declared)throw new IOException("Sparse-GRM stored-entry count differs from header");long absent=samples-diagonalEntries;zeroDiagonals+=absent;if(absent>0||diagonalEntries==0)minimumDiagonal=0;var result=new LinkedHashMap<String,Object>();result.put("dimension",samples);result.put("stored_entries",count);result.put("off_diagonal_pairs",offDiagonal);result.put("diagonal_min",minimumDiagonal);result.put("diagonal_max",maximumDiagonal);result.put("unstored_zero_diagonals",absent);result.put("total_zero_diagonals",zeroDiagonals);result.put("diagonal_interpretation","Unstored symmetric-matrix entries are zero;no unit diagonal or positive definiteness is inferred.");result.put("off_diagonal_min",offDiagonal==0?null:minimumOffDiagonal);result.put("off_diagonal_max",offDiagonal==0?null:maximumOffDiagonal);result.put("triangle",triangle==0?"diagonal-only":triangle>0?"lower":"upper");result.put("ordering",rowSorted?"row-major":"column-major");return result;
    }
    static void keys(Map<?,?> value,Set<String> allowed)throws IOException {for(Object key:value.keySet())if(!(key instanceof String text)||!allowed.contains(text))throw new IOException("Unknown typed SAIGE field: "+key);}
    static Map<?,?> map(Object value)throws IOException {if(!(value instanceof Map<?,?> map))throw new IOException("Require a typed SAIGE JSON object");return map;}
    static String text(Map<?,?> map,String name)throws IOException {Object value=map.get(name);if(!(value instanceof String text)||text.isBlank())throw new IOException("Require explicit string: "+name);return text;}
    static double number(Map<?,?> map,String name,double min,double max)throws IOException {Object value=map.get(name);if(!(value instanceof Number n)||!Double.isFinite(n.doubleValue())||n.doubleValue()<min||n.doubleValue()>max)throw new IOException("Require explicit finite numeric "+name+" in ["+min+","+max+"]");return n.doubleValue();}
    static long whole(Map<?,?> map,String name,long min,long max)throws IOException {double value=number(map,name,min,max);if(value!=Math.rint(value))throw new IOException("Require an exact integer: "+name);return (long)value;}
    private static long optional(Map<?,?> map,String name,long fallback,long min,long max)throws IOException {return map.containsKey(name)?whole(map,name,min,max):fallback;}
    static String line(BufferedReader reader,int maximum)throws IOException {var result=new StringBuilder();int value;while((value=reader.read())!=-1){if(value=='\n')return result.toString();if(value=='\r'){reader.mark(1);int next=reader.read();if(next!='\n'&&next!=-1)reader.reset();return result.toString();}if(result.length()>=maximum)throw new IOException("SAIGE text row exceeds declared line bound");result.append((char)value);}return result.isEmpty()?null:result.toString();}
}
